  if (!astComments) {
    return;
  }

  for (let i = 0; i < astComments.length; ++i) {
    if (privateUtil.isNodeIgnoreComment(astComments[i])) {
      // If there's a prettier-ignore, we're not printing that sub-tree so we
      // don't know if the comments was printed or not.
      return;
